/-- The group given by the presentation ⟨a, b | a⁵ = b² = 1, ba = a²b⟩ is isomorphic to ℤ/2ℤ. -/
theorem group_presentation_iso_Z2 :
  let G := PresentedGroup (fun (_ : Fin 2) => True)
  let a := PresentedGroup.of (0 : Fin 2)
  let b := PresentedGroup.of (1 : Fin 2)
  let rels : Set (FreeGroup (Fin 2)) := {
    FreeGroup.of 0 ^ 5,
    FreeGroup.of 1 ^ 2,
    FreeGroup.of 1 * FreeGroup.of 0 * (FreeGroup.of 0 ^ 2 * FreeGroup.of 1)⁻¹
  }
  Nonempty ((PresentedGroup.of (fun (_ : Fin 2) => True)) ⧸ 
    (Subgroup.normalClosure (Set.range (fun r => QuotientGroup.mk r) ∩ 
    Set.range (fun r => (r : G)))) ≃* ZMod 2) := by sorry

